mapper.select:
SELECT 
FROM mt_poi_traffic_daily
WHERE shop_id = #{shopId}
  AND biz_date = #{bizDate}
  AND flow_prop = #{flowProp}
LIMIT 1

mapper.insert:
INSERT INTO mt_poi_traffic_daily (
    shop_id, biz_date, flow_prop, exposure_count, visit_count, payload_json, create_time, update_time
) VALUES (
    #{shopId}, #{bizDate}, #{flowProp}, #{exposureCount}, #{visitCount}, #{payloadJson}, #{createTime}, #{updateTime}
)
ON DUPLICATE KEY UPDATE
    exposure_count = VALUES(exposure_count),
    visit_count = VALUES(visit_count),
    payload_json = VALUES(payload_json),
    update_time = VALUES(update_time)

mapper.select:
SELECT COALESCE(SUM(exposure_count), 0)
FROM mt_poi_traffic_daily
WHERE shop_id = #{shopId}
  AND flow_prop = #{flowProp}
  AND biz_date >= #{fromInclusive}
  AND biz_date < #{toExclusive}
